const MOD_SECTION = "<section class=\"page\" id=\"page-feedback-appeal\">\n<div class=\"page-head\">\n<div><div class=\"eyebrow\">Moderation / Staging</div><h1>Feedback &amp; Appeal (Beta Feature)</h1>\n<p>Review user feedback and appeals from the ArcScriptCenter staging database, with public replies, private notes, and a receipt-protected audit trail.</p>\n</div><span class=\"tag blue\">STAGING ONLY</span>\n</div>\n<div class=\"fa-muted-warning\" role=\"note\"><b>Private admin workspace.</b> Do not share your Admin Key or screenshots containing personal submissions. A claimed Roblox UserId is not verified identity. Spam Mail is admin-only.</div>\n<div class=\"panel panel-pad\" style=\"margin-top:18px;margin-bottom:17px\">\n<div class=\"panel-top\"><div><h3>Admin access</h3><p>Admin Key stays in this tab's memory only; it is never added to URLs or browser storage.</p></div><span class=\"tag orange\" id=\"faAuthBadge\">LOCKED</span></div>\n<div class=\"fa-controls\">\n<div class=\"field\"><label for=\"faAdminKey\">Cloudflare Staging Admin Key</label><input autocomplete=\"new-password\" id=\"faAdminKey\" placeholder=\"Enter Staging Admin Key\" spellcheck=\"false\" type=\"password\"/></div>\n<button class=\"btn btn-primary\" id=\"faUnlock\" type=\"button\">Unlock</button>\n<button class=\"btn\" id=\"faLock\" type=\"button\">Lock</button>\n</div>\n<p aria-live=\"polite\" class=\"fa-inline-status\" id=\"faStatus\" role=\"status\">Locked. Enter a key to view cases.</p>\n</div>\n<div aria-label=\"Feedback and appeal queue summary\" class=\"fa-queue-overview\" id=\"faQueueOverview\">\n<div class=\"fa-queue-stat\"><span>All active cases</span><strong id=\"faSummaryTotal\">—</strong><small>Feedback + Appeal</small></div>\n<div class=\"fa-queue-stat\"><span>Awaiting review</span><strong id=\"faSummaryReviewing\">—</strong><small>All submissions marked Reviewing</small></div>\n<div class=\"fa-queue-stat\"><span>Appeals awaiting review</span><strong id=\"faSummaryAppeals\">—</strong><small>Prioritize when convenient</small></div>\n<div class=\"fa-queue-stat\"><span>Submitted in last 24 h</span><strong id=\"faSummary24h\">—</strong><small>Rolling window (UTC timestamps)</small></div>\n</div>\n<div aria-label=\"Age of cases awaiting review\" class=\"fa-queue-overview\">\n<div class=\"fa-queue-stat\"><span>Reviewing ≥24 hours</span><strong id=\"faAge24h\">—</strong><small>Pending since first submission</small></div>\n<div class=\"fa-queue-stat\"><span>Reviewing ≥3 days</span><strong id=\"faAge72h\">—</strong><small>Consider reviewing older cases</small></div>\n<div class=\"fa-queue-stat\"><span>Reviewing ≥7 days</span><strong id=\"faAge7d\">—</strong><small>No automatic decisions or deadlines</small></div>\n<div class=\"fa-queue-stat\"><span>Marked for follow-up</span><strong id=\"faSummaryFollowup\">—</strong><small>Manual moderator flags on Reviewing cases</small></div>\n<div class=\"fa-queue-stat\"><span>Due / overdue follow-ups</span><strong id=\"faSummaryOverdue\">—</strong><small>Due date reached · Manual review needed</small></div>\n<div class=\"fa-queue-stat\"><span>Due in 24 hours</span><strong id=\"faSummaryDueSoon\">—</strong><small>Scheduled, not yet due</small></div>\n<div class=\"fa-queue-stat\"><span>No follow-up date</span><strong id=\"faSummaryNoDue\">—</strong><small>Marked but not scheduled</small></div>\n<div class=\"fa-queue-stat\"><span>Due after 24 hours</span><strong id=\"faSummaryLater\">—</strong><small>Scheduled beyond tomorrow</small></div>\n</div>\n<div class=\"fa-queue-summary-actions\">\n<p aria-live=\"polite\" id=\"faSummaryAsOf\">Unlock to view private queue totals.</p>\n<div style=\"display:flex;align-items:center;flex-wrap:wrap;gap:8px\">\n<button class=\"btn btn-soft fa-queue-cta\" id=\"faShowPendingAppeals\" type=\"button\">View reviewing appeals</button>\n<button class=\"btn btn-soft fa-queue-cta\" id=\"faShowFollowups\" type=\"button\">View follow-ups</button>\n<button class=\"btn btn-soft fa-queue-cta\" id=\"faShowOverdue\" type=\"button\">View overdue</button>\n<button class=\"btn btn-soft fa-queue-cta\" id=\"faShowDueSoon\" type=\"button\">Due next 24 h</button>\n<button class=\"btn btn-soft fa-queue-cta\" id=\"faShowNoDue\" type=\"button\">Without due date</button>\n</div>\n</div>\n\n<div class=\"panel panel-pad fa-users-panel\" id=\"faUsersCase\" style=\"margin:18px 0\">\n <div class=\"panel-top\"><div><h3>User's Case</h3><p>Find case groups by Roblox UserId or a Username already saved in Ban Management. A claimed UserId is <strong>not verified ownership</strong>.</p></div><span class=\"tag blue\">ADMIN ONLY · STAGING</span></div>\n <div class=\"fa-control-row\">\n  <label for=\"faUsersSearch\">Search User\n   <input id=\"faUsersSearch\" type=\"search\" maxlength=\"40\" autocomplete=\"off\" spellcheck=\"false\" placeholder=\"Username / UserId (blank = all)\"/>\n  </label>\n  <button type=\"button\" class=\"btn btn-primary\" id=\"faUsersLoad\">Load User's Case</button>\n  <button type=\"button\" class=\"btn\" id=\"faTrashLoad\">View Trash / Refresh</button>\n </div>\n <p class=\"fa-inline-status\" id=\"faUsersStatus\" role=\"status\" aria-live=\"polite\">Unlock Admin access, then select Load User's Case.</p>\n <div class=\"fa-users-grid\" id=\"faUsersGroups\"></div>\n <div class=\"fa-users-case-contents\" id=\"faUsersCases\" hidden></div>\n <section id=\"faUnknownTrash\" class=\"fa-unknown-trash\" hidden aria-label=\"Unknown Feedback Trash\">\n  <h4>Unknown Case Trash</h4>\n  <p class=\"fa-inline-status\">Admin can restore before the 30-day deadline. Expired cases are deleted by a scheduled STAGING Worker.</p>\n  <p class=\"fa-inline-status\" id=\"faTrashStatus\" aria-live=\"polite\">Not loaded.</p>\n  <div id=\"faTrashCases\"></div>\n </section>\n</div>\n<div class=\"fa-layout\">\n<div class=\"panel panel-pad\">\n<div class=\"panel-top\"><div><h3>Submitted cases</h3><p>Filter status and submission type.</p></div><span class=\"tag blue\" id=\"faCount\">—</span></div>\n<div class=\"fa-control-row\">\n<label for=\"faStatusFilter\">Status<select id=\"faStatusFilter\"><option value=\"reviewing\">Reviewing</option><option value=\"approved\">Approved</option><option value=\"denied\">Denied</option><option value=\"violation\">Violation</option><option value=\"spam_mail\">Spam Mail (Admin only)</option></select></label>\n<label for=\"faKindFilter\">Type<select id=\"faKindFilter\"><option value=\"all\">All</option><option value=\"feedback\">Feedback</option><option value=\"appeal\">Appeal</option></select></label>\n<label for=\"faSortOrder\">Order<select id=\"faSortOrder\"><option value=\"newest\">Newest first</option><option value=\"oldest\">Oldest first</option></select></label>\n<label for=\"faMinAge\">Created ago<select id=\"faMinAge\"><option value=\"0\">Any age</option><option value=\"86400\">At least 24 hours</option><option value=\"259200\">At least 3 days</option><option value=\"604800\">At least 7 days</option></select></label>\n<label for=\"faFollowupFilter\">Follow-up<select id=\"faFollowupFilter\"><option value=\"all\">All cases</option><option value=\"only\">Marked only</option></select></label>\n<label for=\"faDueFilter\">Due window<select id=\"faDueFilter\">\n<option value=\"all\">Any due date</option>\n<option value=\"overdue\">Due now / overdue</option>\n<option value=\"next24\">Next 24 hours</option>\n<option value=\"later\">After next 24 hours</option>\n<option value=\"unscheduled\">No due date</option>\n<option value=\"scheduled\">Any scheduled date</option>\n</select></label>\n<label class=\"fa-search-field\" for=\"faSearch\">Search all cases\n          <input autocomplete=\"off\" id=\"faSearch\" maxlength=\"80\" placeholder=\"Server search: ID or topic\" spellcheck=\"false\" type=\"search\"/>\n</label>\n<button class=\"btn\" id=\"faRefresh\" type=\"button\">Refresh</button>\n</div>\n<p class=\"fa-inline-status\">Due-window filters query all flagged Reviewing cases on the server, not only the loaded page. Date buckets use the initial page's time while paging; click Refresh for current results. No automatic moderation or reminders.</p>\n<div class=\"fa-case-jump\"> <label for=\"faJumpCaseId\">Open a case by Case ID          <input autocomplete=\"off\" id=\"faJumpCaseId\" inputmode=\"text\" maxlength=\"36\" placeholder=\"UUID (case ID only)\" spellcheck=\"false\" type=\"text\"/> </label> <button class=\"btn btn-soft\" id=\"faJumpCase\" type=\"button\">Open case</button> </div> <div class=\"fa-case-list\" id=\"faCaseList\"><div class=\"fa-empty\">Unlock to load cases.</div></div>\n<div aria-label=\"Case list pagination\" class=\"fa-pagination\">\n<button class=\"btn\" disabled=\"\" id=\"faPagePrev\" type=\"button\">Previous</button>\n<span aria-live=\"polite\" class=\"fa-page-label\" id=\"faPageLabel\">Unlock to browse cases</span>\n<button class=\"btn\" disabled=\"\" id=\"faPageNext\" type=\"button\">Next</button>\n<label for=\"faPageSize\">Per page<select aria-label=\"Cases per page\" id=\"faPageSize\"><option value=\"25\">25</option><option value=\"50\">50</option></select></label>\n</div>\n</div>\n<div class=\"panel panel-pad fa-detail\">\n<div class=\"panel-top\"><div><h3>Case review</h3><p id=\"faSelectedHint\">Select a case from the list.</p></div><span class=\"tag\" id=\"faSelectedStatus\">—</span></div>\n<div aria-label=\"Selected case actions\" class=\"fa-case-tools\"> <button class=\"btn btn-ghost\" disabled=\"\" id=\"faPreviousCase\" type=\"button\">Previous case</button> <button class=\"btn btn-ghost\" disabled=\"\" id=\"faNextCase\" type=\"button\">Next case</button> <button class=\"btn btn-soft\" disabled=\"\" id=\"faCopyCaseId\" type=\"button\">Copy Case ID</button> <button class=\"btn btn-soft\" disabled=\"\" id=\"faCopyCaseLink\" type=\"button\">Copy case link</button> </div> <div class=\"fa-empty\" id=\"faCaseDetail\" style=\"margin-top:15px\">No case selected.</div>\n<div class=\"fa-followup-actions\" hidden=\"\" id=\"faFollowupTools\">\n<button class=\"btn btn-soft\" disabled=\"\" id=\"faFollowupToggle\" type=\"button\">Mark for follow-up</button>\n<small id=\"faFollowupHint\">Manual flag, not a moderation decision. Reviewing cases only.</small>\n</div>\n<div aria-label=\"Private follow-up details\" class=\"fa-followup-details\" hidden=\"\" id=\"faFollowupDetails\">\n<div><strong>Follow-up Details — Admin only</strong><p class=\"hint\">Only moderators can read this note and date. No email, push notification, or automatic decision will be sent.</p></div>\n<label for=\"faFollowupNote\">Follow-up reason (0–500 characters)\n          <textarea id=\"faFollowupNote\" maxlength=\"500\" placeholder=\"Optional internal reason for returning to this case. Avoid entering unnecessary personal data.\" spellcheck=\"true\"></textarea>\n</label>\n<label for=\"faFollowupDue\">Return to this case (optional — device local time)\n          <input autocomplete=\"off\" id=\"faFollowupDue\" step=\"60\" type=\"datetime-local\"/>\n<span class=\"hint\">Leave blank for no date. A selected date must be 1 minute to 365 days in the future. Past dates are shown as overdue, not auto-processed.</span>\n</label>\n<div class=\"actions\"><button class=\"btn btn-primary\" id=\"faFollowupSaveDetails\" type=\"button\">Confirm &amp; save follow-up details</button><button class=\"btn btn-ghost\" id=\"faFollowupResetDetails\" type=\"button\">Reset form</button></div>\n<p aria-live=\"polite\" class=\"hint\" id=\"faFollowupDetailStatus\" role=\"status\">Details are not saved until you confirm.</p>\n</div>\n<div hidden=\"\" id=\"faEditor\">\n<div class=\"fa-edit\">\n<label for=\"faDecision\">Decision<select id=\"faDecision\"><option value=\"reviewing\">Reviewing</option><option value=\"approved\">Approved</option><option value=\"denied\">Denied</option><option value=\"violation\">Violation</option><option value=\"spam_mail\">Spam Mail</option></select></label>\n<label for=\"faPublicNote\">Public reply (up to 800 characters)<textarea id=\"faPublicNote\" maxlength=\"800\" placeholder=\"Visible to the person with the Case ID + Receipt. Keep private information out.\" spellcheck=\"true\"></textarea></label>\n<label for=\"faAdminNote\">Internal moderator note (up to 1,000 characters)<textarea id=\"faAdminNote\" maxlength=\"1000\" placeholder=\"Admin-only note — never sent to users.\" spellcheck=\"true\"></textarea></label>\n<div class=\"form-actions\"><button class=\"btn btn-primary\" id=\"faSave\" type=\"button\">Confirm &amp; save decision</button><button class=\"btn btn-ghost\" id=\"faReset\" type=\"button\">Reset changes</button></div>\n<p aria-live=\"polite\" class=\"fa-inline-status\" id=\"faSaveStatus\" role=\"status\">Refresh the selected case before saving if another reviewer has updated it.</p>\n</div>\n<div class=\"inline-divider\"></div>\n<div class=\"subhead\"><h4>Review History</h4><span class=\"tag blue\" id=\"faHistoryCount\">—</span></div>\n<div class=\"fa-history\" id=\"faHistory\"><div class=\"fa-empty\">Select a case to see the history.</div></div>\n</div>\n</div>\n</div>\n<div class=\"panel panel-pad fa-activity\" id=\"faActivityPanel\">\n<div class=\"panel-top\"><div><h3>Recent Activity</h3><p>Latest Feedback &amp; Appeal events from Staging. Admin access required.</p></div><span class=\"tag blue\">AUDIT</span></div>\n<div class=\"fa-activity-controls\">\n<label for=\"faActivityFilter\">Event type\n        <select id=\"faActivityFilter\"><option value=\"all\">All recent events</option><option value=\"submitted\">Submitted / Imported</option><option value=\"edited\">User edits</option><option value=\"reviewed\">Moderator reviews</option><option value=\"removed\">Removed</option></select>\n</label>\n<button class=\"btn btn-soft\" disabled=\"\" id=\"faActivityRefresh\" type=\"button\">Refresh activity</button>\n</div>\n<p aria-live=\"polite\" class=\"fa-activity-status\" id=\"faActivityStatus\" role=\"status\">Unlock to see the 25 latest events.</p>\n<div class=\"fa-activity-list\" id=\"faActivityList\"><div class=\"fa-empty\">Activity is private until admin unlock.</div></div>\n<p class=\"fa-inline-status\">Events are displayed newest first. Filters apply to the 25 fetched events; use a Case ID to open its complete history. No automatic polling.</p>\n</div>\n</section>";
const MOD_NAV = "<button type=\"button\" class=\"nav-item\" data-page=\"feedback-appeal\" id=\"asc1649FeedbackNav\" aria-label=\"Feedback and Appeal\"><svg aria-hidden=\"true\"><use href=\"#i-check\"></use></svg> Feedback &amp; Appeal (Beta) <span class=\"mini\" id=\"faNavPending\">—</span></button>";
const MOD_STYLES = "/* Stage 16.41 — Feedback & Appeal is part of the main ArcScriptCenter Dashboard. */\n.fa-layout{display:grid;grid-template-columns:minmax(280px,.85fr) minmax(320px,1.3fr);gap:17px;align-items:start}\n.fa-controls{display:grid;grid-template-columns:1fr auto auto;gap:10px;align-items:end;margin-top:16px}\n.fa-controls .field label{display:block;margin-bottom:6px}\n.fa-control-row{display:flex;flex-wrap:wrap;align-items:center;gap:9px;margin:12px 0 15px}\n.fa-control-row select,.fa-control-row input,.fa-controls input,.fa-edit textarea,.fa-edit select{width:100%;background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px;min-height:40px}\n.fa-controls input:focus,.fa-edit textarea:focus,.fa-edit select:focus{outline:2px solid #73a6ff66;outline-offset:1px}\n.fa-control-row>label{flex:1;min-width:120px;color:var(--sub);font-weight:650;font-size:12px}\n.fa-control-row label select{margin-top:6px}\n    .fa-case-list{display:grid;gap:9px;max-height:620px;overflow:auto;overscroll-behavior:contain;padding:2px}\n    .fa-case-age{display:inline-block;width:fit-content;margin-top:4px;padding:2px 8px;font-size:11px;font-weight:700;border:1px solid #506783;border-radius:6px;color:var(--sub);background:#32476333}\n    .fa-case-age[data-age=\"72h\"]{color:#ffcb8e;border-color:#906b3c;background:#8b602329}\n     .fa-case-age[data-age=\"7d\"]{color:#ffb4be;border-color:#9a4e62;background:#9a4e621f}\n    .fa-followup-mark{display:inline-flex;align-items:center;width:fit-content;margin-top:6px;padding:3px 9px;border:1px solid #8f7144;border-radius:7px;background:#e4a44e1c;color:#ffd293;font-size:11px;font-weight:800;letter-spacing:.25px}\n    .fa-followup-actions{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin:15px 0 9px;padding:11px 12px;border:1px solid var(--line);border-radius:11px;background:var(--surface2)}\n    .fa-followup-actions .btn{min-height:40px}\n    .fa-followup-actions small{flex:1;min-width:160px;color:var(--sub);line-height:1.6}\n    .fa-followup-details{margin:0 0 18px;padding:16px;border:1px solid var(--line);border-radius:12px;background:var(--surface2);display:grid;gap:12px}\n    .fa-followup-details[hidden]{display:none}\n    .fa-followup-details label{font-size:12px;font-weight:700;color:var(--sub);display:grid;gap:6px}\n    .fa-followup-details textarea,.fa-followup-details input{font:inherit;width:100%;color:var(--text);background:var(--input);border:1px solid var(--line);border-radius:9px;padding:11px;min-height:42px}\n    .fa-followup-details textarea{min-height:105px;resize:vertical}\n    .fa-followup-details .hint{color:var(--muted);font-size:11px;font-weight:400}\n    .fa-followup-details .actions{display:flex;align-items:center;gap:10px;flex-wrap:wrap}\n    .fa-followup-due{display:inline-flex;align-items:center;border:1px solid #8b6a27;color:#f5cb72;background:#5f452322;border-radius:6px;padding:3px 7px;font-size:10px;font-weight:800;margin-left:6px}\n    .fa-followup-due[data-overdue=\"true\"]{color:#ffb6ad;border-color:#984b49;background:#7a2b2b22}\n\n.fa-pagination{display:flex;gap:8px;align-items:center;flex-wrap:wrap;margin-top:15px;padding-top:12px;border-top:1px solid var(--line)}\n.fa-pagination .btn{min-width:76px}.fa-page-label{color:var(--sub);font-size:12px;flex:1;min-width:160px}\n.fa-case-jump{display:flex;gap:9px;align-items:end;flex-wrap:wrap;margin:12px 0}\n.fa-case-jump label{flex:1;min-width:230px;font-size:12px;color:var(--sub)}\n.fa-case-jump input{display:block;width:100%;margin-top:6px;background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px;min-height:42px}\n.fa-case-tools{display:flex;gap:8px;flex-wrap:wrap;margin:12px 0 4px}\n.fa-case-tools button{min-height:42px}\n/* Stage 16.44: admin-only recent moderation activity. */\n.fa-activity{margin-top:17px}\n.fa-activity-controls{display:flex;align-items:end;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:12px 0}\n.fa-activity-controls label{display:grid;gap:5px;font-size:12px;font-weight:650;color:var(--sub);min-width:170px}\n.fa-activity-controls select{background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:9px;padding:10px;min-height:42px}\n.fa-activity-list{display:grid;gap:8px;max-height:450px;overflow:auto;overscroll-behavior:contain}\n.fa-activity-row{display:flex;justify-content:space-between;align-items:center;gap:14px;flex-wrap:wrap;background:var(--surface2);border:1px solid var(--line);border-radius:11px;padding:12px 14px}\n.fa-activity-row-main{min-width:180px;flex:1;overflow-wrap:anywhere}\n.fa-activity-row-main strong{font-size:12px;display:block}\n.fa-activity-row-main small{font-size:11px;color:var(--muted);display:block;margin-top:3px}\n.fa-activity-row .btn{min-height:38px}\n.fa-activity-status{font-size:12px;color:var(--muted);min-height:18px}\n\n.fa-pagination label{display:inline-flex;align-items:center;gap:7px;color:var(--sub);font-size:12px}\n.fa-pagination select{background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:8px;padding:8px;min-height:36px}\n.fa-case{width:100%;text-align:left;padding:12px;border:1px solid var(--line);background:var(--surface2);border-radius:12px;color:var(--text);display:grid;gap:5px;cursor:pointer;overflow-wrap:anywhere}\n.fa-case:hover{border-color:#7c9aff}.fa-case[aria-pressed=\"true\"]{border-color:#92b7ff;background:var(--surface3);outline:1px solid #92b7ff77}\n.fa-case-top{display:flex;align-items:center;gap:8px;justify-content:space-between;font-size:11px}.fa-case strong{font-size:13px}.fa-case small{font-size:11px;color:var(--muted)}\n.fa-pill{display:inline-block;border:1px solid var(--line);border-radius:999px;padding:2px 8px;color:var(--sub);white-space:nowrap;font-size:10px;font-weight:750}\n.fa-detail{min-height:220px}.fa-detail dl{display:grid;grid-template-columns:135px 1fr;gap:7px 12px;font-size:12px;line-height:1.5}.fa-detail dt{color:var(--muted)}.fa-detail dd{margin:0;overflow-wrap:anywhere;white-space:pre-wrap}\n.fa-detail-text{padding:12px;background:var(--surface2);border:1px solid var(--line);border-radius:10px;max-height:250px;overflow:auto;white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px;line-height:1.65}\n.fa-edit{display:grid;gap:12px;margin-top:16px}.fa-edit label{display:grid;gap:5px;font-size:12px;font-weight:750;color:var(--sub)}.fa-edit textarea{min-height:96px;resize:vertical;font-weight:400}.fa-history{display:grid;gap:8px;max-height:360px;overflow:auto;overscroll-behavior:contain}\n.fa-event{border-left:3px solid #789cff;border-radius:7px;background:var(--surface2);padding:11px 13px;font-size:12px;overflow-wrap:anywhere}.fa-event b{display:block}.fa-event small{display:block;margin-top:2px;color:var(--muted)}.fa-event p{white-space:pre-wrap;margin:7px 0 0}\n.fa-inline-status{font-size:12px;color:var(--sub);min-height:18px;overflow-wrap:anywhere}\n.fa-empty{padding:35px 14px;border:1px dashed var(--line);border-radius:13px;color:var(--muted);text-align:center;font-size:13px}\n.fa-muted-warning{background:#d1a15613;border:1px solid #d1a15649;color:var(--sub);padding:12px;border-radius:11px;font-size:12px}\n@media (max-width:1050px){.fa-layout{grid-template-columns:1fr}.fa-case-list{max-height:380px}}\n@media (max-width:520px){.fa-controls{grid-template-columns:1fr 1fr}.fa-controls .field{grid-column:span 2}.fa-detail dl{grid-template-columns:1fr}.fa-detail dt{margin-top:4px}.fa-detail dd{margin-bottom:5px}}\n\n\n/* Stage 16.41 — compact, authenticated queue overview; does not alter legacy panels. */\n.fa-queue-overview{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;margin:0 0 16px}\n.fa-queue-stat{min-height:102px;padding:14px 16px;border:1px solid var(--line);background:var(--surface);border-radius:14px;display:flex;flex-direction:column;gap:4px;justify-content:center}\n.fa-queue-stat span{font-size:11px;color:var(--sub);font-weight:700}\n.fa-queue-stat strong{font-size:28px;line-height:1.2;font-weight:800;color:var(--text);font-variant-numeric:tabular-nums}\n.fa-queue-stat small{color:var(--muted);font-size:10px;line-height:1.5}\n.fa-queue-summary-actions{display:flex;align-items:center;justify-content:space-between;gap:10px;flex-wrap:wrap;margin:0 0 17px}\n.fa-queue-summary-actions p{margin:0;color:var(--muted);font-size:11px}\n.fa-queue-cta{min-height:35px}\n.fa-search-field{flex:1.2;min-width:135px;color:var(--sub);font-size:12px;font-weight:700}\n.fa-search-field input{display:block;width:100%;min-height:40px;margin-top:6px;padding:9px 11px;background:var(--input);color:var(--text);border:1px solid var(--line);border-radius:9px}\n.fa-search-field input:focus{outline:2px solid #739fff77;outline-offset:1px}\n@media(max-width:980px){.fa-queue-overview{grid-template-columns:repeat(2,minmax(0,1fr))}}\n@media(max-width:520px){.fa-queue-stat{padding:11px}.fa-queue-stat strong{font-size:24px}}\n\n/* STAGING User's Case and Unknown Trash — appending, not replacing theme. */\n.fa-users-grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:10px;margin:12px 0}\n.fa-user-group,.fa-users-case-row,.fa-trash-row{display:flex;flex-direction:column;gap:7px;align-items:stretch;border:1px solid var(--line);border-radius:10px;padding:12px;background:var(--surface2);min-width:0}\n.fa-user-group{cursor:pointer;color:var(--text);text-align:left;min-height:75px}\n.fa-user-group:focus-visible{outline:2px solid #73a6ff;outline-offset:2px}\n.fa-user-group small,.fa-users-case-row small,.fa-trash-row small{color:var(--sub);overflow-wrap:anywhere}\n.fa-users-case-contents,.fa-unknown-trash{border-top:1px solid var(--line);margin:15px 0;padding-top:15px}\n.fa-users-case-contents[hidden],.fa-unknown-trash[hidden]{display:none!important}\n.fa-case-action-row{display:flex;flex-wrap:wrap;gap:8px;margin-top:5px}\n.fa-case-action-row .btn{min-height:36px}\n.fa-inline-status{overflow-wrap:anywhere}\n";
const MOD_SCRIPT = "'use strict';\n(()=>{\n\n  function asc1649Navigate() {\n    const page=document.getElementById('page-feedback-appeal');\n    const nav=document.getElementById('asc1649FeedbackNav');\n    if(!page || !nav)return;\n    document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el===page));\n    document.querySelectorAll('.nav-item').forEach(el=>{\n      const yes=el===nav;\n      el.classList.toggle('active',yes);\n      if(yes)el.setAttribute('aria-current','page');\n      else el.removeAttribute('aria-current');\n    });\n    const crumb=document.getElementById('breadcrumb');\n    if(crumb)crumb.textContent='Feedback & Appeal (Beta Feature)';\n    document.getElementById('sidebar')?.classList.remove('open');\n    document.getElementById('scrim')?.classList.remove('visible');\n    const menu=document.getElementById('menuBtn');\n    if(menu)menu.setAttribute('aria-label','Open menu');\n    if(!location.hash.startsWith('#feedback-appeal'))\n      history.replaceState(null,'','#feedback-appeal');\n    window.scrollTo({top:0,behavior:'instant'});\n  }\n  const nav=document.getElementById('asc1649FeedbackNav');\n  const pane=document.getElementById('page-feedback-appeal');\n  if(!nav || !pane)return;\n  // Capture before legacy Dashboard router; it doesn't know this new route.\n  nav.addEventListener('click',event=>{\n    event.preventDefault();\n    event.stopImmediatePropagation();\n    asc1649Navigate();\n  },true);\n  window.addEventListener('hashchange',()=>{\n    if(location.hash.startsWith('#feedback-appeal'))asc1649Navigate();\n  });\n  if(location.hash.startsWith('#feedback-appeal'))asc1649Navigate();\n\n  // Stage 16.42: server-wide search and keyset pagination for Feedback & Appeal.\n  // The recovered original Dashboard and all moderation controls use STAGING.\n  // Kept separate to avoid accidentally depending on other Dashboard settings.\n  const FA_STAGING_API = 'https://arcscriptcenter-api-staging.kogpasan14.workers.dev';\n  const faState = {key:'', cases:[], selected:null, loading:false, requestId:0, generation:0,\n    pageCursors:[''],pageIndex:0,nextCursor:null,hasMore:false,matchedTotal:0,dueAsOf:null};\n  let faSearchTimer=null;\n  const faActivityState = {loading:false, events:[]};\n  const faEl = id => document.getElementById(id);\n  const faStatuses = new Set(['reviewing','approved','denied','violation','spam_mail']);\n  const faCaseIdRx = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i;\n  const faFormat = secs => {\n    const n=Number(secs);\n    if(!Number.isFinite(n)||n<=0) return 'Unknown time';\n    return new Date(n*1000).toLocaleString('en-GB',{dateStyle:'medium',timeStyle:'short',timeZone:'Asia/Bangkok'})+' ICT';\n  };\n  const faText = v => String(v ?? '');\n  function faNotice(message,error=false) {\n    const el=faEl('faStatus');el.textContent=message;\n    el.style.color=error?'var(--danger)':'var(--sub)';\n  }\n  function faSaveNotice(message,error=false) {\n    const el=faEl('faSaveStatus');el.textContent=message;\n    el.style.color=error?'var(--danger)':'var(--sub)';\n  }\n  function faSetBusy(v){\n    faState.loading=!!v;\n    for(const id of ['faUnlock','faRefresh','faSave','faStatusFilter','faKindFilter','faSearch',\n      'faPageSize','faSortOrder','faMinAge','faFollowupFilter','faDueFilter','faJumpCase','faJumpCaseId',\n      'faFollowupNote','faFollowupDue','faFollowupSaveDetails','faFollowupResetDetails'])faEl(id).disabled=!!v;\n    faRenderPagination();\n    faUpdateSelectionActions();\n    faUsersUnlocked();\n  }\n  function faNode(name,textContent,className){\n    const el=document.createElement(name);\n    if(textContent!==undefined)el.textContent=faText(textContent);\n    if(className)el.className=className;\n    return el;\n  }\n  async function faRequest(path,method='GET',payload){\n    if(!faState.key)throw new Error('Admin session is locked');\n    const response=await fetch(FA_STAGING_API+path,{\n      method,mode:'cors',credentials:'omit',cache:'no-store',redirect:'error',\n      headers:{'Accept':'application/json','Content-Type':'application/json','X-Admin-Key':faState.key},\n      body:method==='POST'?JSON.stringify(payload):undefined\n    });\n    let data;\n    try{data=await response.json();}catch{throw new Error('Invalid API response (HTTP '+response.status+')');}\n    if(!response.ok||!data.ok){\n      throw new Error(faText(data.error||('HTTP '+response.status))+' (HTTP '+response.status+')');\n    }\n    return data;\n  }\n  function faClearSelected(){\n    faState.selected=null;\n    faEl('faSelectedHint').textContent='Select a case from the list.';\n    faEl('faSelectedStatus').textContent='—';\n    faEl('faCaseDetail').replaceChildren(faNode('div','No case selected.','fa-empty'));\n    faEl('faEditor').hidden=true;\n    faEl('faHistory').replaceChildren();\n    faEl('faFollowupTools').hidden=true;\n    faEl('faFollowupDetails').hidden=true;\n    faEl('faFollowupNote').value='';\n    faEl('faFollowupDue').value='';\n    faEl('faFollowupDetailStatus').textContent='Details are not saved until you confirm.';\n    faEl('faFollowupHint').textContent='Manual flag, not a moderation decision. Reviewing cases only.';\n    faUpdateSelectionActions();\n  }\n  function faRenderSummary(summary){\n    const valid=summary && typeof summary==='object';\n    const numbers={faSummaryTotal:'total',faSummaryReviewing:'reviewing',\n      faSummaryAppeals:'reviewingAppeals',faSummary24h:'submittedLast24Hours'};\n    const aging={faAge24h:'over24Hours',faAge72h:'over72Hours',faAge7d:'over7Days'};\n    const manualCount=Number(summary?.followupReviewing);\n    faEl('faSummaryFollowup').textContent=valid&&Number.isFinite(manualCount)&&manualCount>=0?String(manualCount):'—';\n    for(const [id,key] of [['faSummaryOverdue','overdue'],['faSummaryDueSoon','next24Hours'],\n      ['faSummaryNoDue','unscheduled'],['faSummaryLater','later']]){\n      const n=Number(summary?.followupDue?.[key]);\n      faEl(id).textContent=valid&&summary?.followupDue&&Number.isFinite(n)&&n>=0?String(n):'—';\n    }\n    for(const [id,key] of Object.entries(aging)){\n      const n=Number(summary?.reviewingAging?.[key]);\n      faEl(id).textContent=valid && summary?.reviewingAging && Number.isFinite(n) && n>=0?String(n):'—';\n    }\n    for (const [id,key] of Object.entries(numbers)){\n      const n=Number(summary?.[key]);\n      faEl(id).textContent=valid&&Number.isFinite(n)&&n>=0?String(n):'—';\n    }\n    const updated=Number(summary?.asOf);\n    faEl('faSummaryAsOf').textContent=valid&&updated>0?\n      'Queue totals verified '+faFormat(updated)+' · Click Refresh to update.':\n      'Unlock and refresh to load queue totals.';\n    const badge=faEl('faNavPending');\n    const pending=Number(summary?.reviewing);\n    badge.hidden=!valid || !Number.isFinite(pending) || pending<=0;\n    badge.textContent=valid && Number.isFinite(pending)?String(pending):'—';\n  }\n  function faRenderPagination(){\n    faEl('faPagePrev').disabled=faState.loading||!faState.key||faState.pageIndex<=0;\n    faEl('faPageNext').disabled=faState.loading||!faState.key||!faState.hasMore;\n    faEl('faPageLabel').textContent=faState.key ?\n      'Page '+String(faState.pageIndex+1)+' · '+String(faState.cases.length)+\n      ' shown · '+String(faState.matchedTotal)+' matches' : 'Unlock to browse cases';\n  }\n  function faResetPages(){\n    faState.pageIndex=0;faState.pageCursors=[''];faState.nextCursor=null;\n    faState.hasMore=false;faState.matchedTotal=0;faState.dueAsOf=null;\n    faRenderPagination();\n  }\n  function faCaseAgeLabel(c){\n    const n=Number(c.created_unix);\n    if(!Number.isFinite(n)||n<=0)return 'Age unknown';\n    const seconds=Math.max(0,Math.floor(Date.now()/1000)-n);\n    const time=seconds<3600 ? Math.floor(seconds/60)+' min' :\n      seconds<86400 ? Math.floor(seconds/3600)+' h' : Math.floor(seconds/86400)+' d';\n    return c.status==='reviewing'?'Waiting '+time:'Created '+time+' ago';\n  }\n  function faCaseAgeBand(c){\n    if(c.status!=='reviewing')return 'none';\n    const seconds=Math.max(0,Math.floor(Date.now()/1000)-Number(c.created_unix));\n    return seconds>=604800?'7d':seconds>=259200?'72h':'none';\n  }\n  function faRenderList(){\n    const visible=faState.cases;\n    faEl('faCount').textContent=String(faState.matchedTotal)+' matches';\n    const list=faEl('faCaseList');list.replaceChildren();\n    for(const c of visible){\n      const btn=faNode('button',undefined,'fa-case');btn.type='button';\n      btn.setAttribute('aria-pressed',String(faState.selected?.id===c.id));\n      const top=faNode('div',undefined,'fa-case-top');\n      top.append(faNode('span',faText(c.kind||'Unknown').toUpperCase()),faNode('span',faText(c.status||'Unknown'),'fa-pill'));\n      btn.append(top,faNode('strong',c.topic||'(Untitled)'),faNode('small',faText(c.id)));\n      btn.append(faNode('small','Updated '+faFormat(c.updated_unix)));\n      const age=faNode('span',faCaseAgeLabel(c),'fa-case-age');\n      age.dataset.age=faCaseAgeBand(c);btn.append(age);\n      if(Number(c.followup)===1){\n        btn.append(faNode('span','FOLLOW-UP','fa-followup-mark'));\n        const due=Number(c.followup_due_unix);\n        if(Number.isFinite(due)&&due>0){\n          const overdue=due<=Math.floor(Date.now()/1000);\n          const tag=faNode('span',overdue?'OVERDUE':'DUE '+faFormat(due),'fa-followup-due');\n          tag.dataset.overdue=String(overdue);btn.append(tag);\n        }\n      }\n      btn.addEventListener('click',()=>{void faSelectCase(c);});\n      list.append(btn);\n    }\n    if(!visible.length)list.append(faNode('div','No cases match these filters.','fa-empty'));\n    faRenderPagination();\n    faUpdateSelectionActions();\n  }\n  function faDetailLine(label,value){\n    const frag=document.createDocumentFragment();\n    frag.append(faNode('dt',label),faNode('dd',value));return frag;\n  }\n  function faRenderDetail(c){\n    faEl('faSelectedHint').textContent='Case '+faText(c.id)+' · '+faText(c.kind);\n    faEl('faSelectedStatus').textContent=faText(c.status);\n    const dl=document.createElement('dl');\n    dl.append(faDetailLine('Case ID',c.id),faDetailLine('Type',c.kind),faDetailLine('Status',c.status));\n    if(c.kind==='feedback'||c.kind==='appeal')dl.append(faDetailLine('Claimed Roblox UserId',faText(c.claimed_user_id??'Not provided')+' (unverified)'));\n    dl.append(faDetailLine('Revision',c.revision),faDetailLine('Created',faFormat(c.created_unix)),\n      faDetailLine('Case age',faCaseAgeLabel(c)),faDetailLine('Updated',faFormat(c.updated_unix)));\n    dl.append(faDetailLine('Manual follow-up',Number(c.followup)===1?'Marked':'Not marked'));\n    if(Number(c.followup_updated_unix)>0)\n      dl.append(faDetailLine('Follow-up changed',faFormat(c.followup_updated_unix)));\n    if(Number(c.followup)===1 && Number(c.followup_due_unix)>0){\n      const due=Number(c.followup_due_unix);\n      dl.append(faDetailLine('Return date',faFormat(due)+(due<=Math.floor(Date.now()/1000)?' · OVERDUE':'')));\n    }\n    const detail=faEl('faCaseDetail');detail.className='';detail.replaceChildren(dl);\n    detail.append(faNode('h3','Topic'),faNode('div',c.topic||'','fa-detail-text'));\n    detail.append(faNode('h3','Description'),faNode('div',c.description||'','fa-detail-text'));\n    faEl('faEditor').hidden=false;\n    faEl('faDecision').value=faStatuses.has(c.status)?c.status:'reviewing';\n    faEl('faPublicNote').value=faText(c.public_note);\n    faEl('faAdminNote').value=faText(c.admin_note);\n    faEl('faFollowupTools').hidden=false;\n    const marked=Number(c.followup)===1;\n    faEl('faFollowupDetails').hidden=!(marked && c.status==='reviewing');\n    faEl('faFollowupNote').value=marked?faText(c.followup_note):'';\n    faEl('faFollowupDue').value=marked?faFollowupDateToInput(c.followup_due_unix):'';\n    faEl('faFollowupDetailStatus').textContent='Details are not saved until you confirm.';\n    faEl('faFollowupToggle').textContent=marked?'Clear follow-up':'Mark for follow-up';\n    faEl('faFollowupHint').textContent=c.status==='reviewing'?\n      (marked?'Marked by a moderator. Clearing requires confirmation.':'Manual flag for later review; does not change status or review outcome.'):\n      'Closed case: follow-up cannot be changed.';\n    faSaveNotice('Changes are not saved until confirmed.');\n    faRenderList();\n    faUpdateSelectionActions();\n  }\n  function faRenderHistory(events){\n    const history=faEl('faHistory');history.replaceChildren();\n    const rows=Array.isArray(events)?events:[];\n    faEl('faHistoryCount').textContent=rows.length+' events';\n    for(const e of rows){\n      const event=faNode('div',undefined,'fa-event');\n      event.append(faNode('b',faText(e.type)+' · '+faText(e.status)));\n      event.append(faNode('small','Revision '+faText(e.revision)+' · '+faFormat(e.createdAt)));\n      if(e.publicNote)event.append(faNode('p',e.publicNote));\n      history.append(event);\n    }\n    if(!rows.length)history.append(faNode('div','No recorded events.','fa-empty'));\n  }\n  // A deep link contains ONLY the opaque case ID; never append a key or receipt.\n  function faReadDeepLink(){\n    const m=/^#feedback-appeal\\/case\\/([0-9a-f-]{36})$/i.exec(location.hash);\n    return m && faCaseIdRx.test(m[1]) ? m[1] : null;\n  }\n  function faCaseLink(id){\n    return location.origin+location.pathname+'#feedback-appeal/case/'+encodeURIComponent(id);\n  }\n  function faUpdateSelectionActions(){\n    const id=faState.selected?.id||null;\n    const idx=id?faState.cases.findIndex(x=>x.id===id):-1;\n    const canUse=!!faState.key && !faState.loading;\n    faEl('faPreviousCase').disabled=!canUse || idx<=0;\n    faEl('faNextCase').disabled=!canUse || idx<0 || idx>=faState.cases.length-1;\n    faEl('faCopyCaseId').disabled=!canUse || !id;\n    faEl('faCopyCaseLink').disabled=!canUse || !id;\n    faEl('faFollowupToggle').disabled=!canUse || !id || faState.selected?.status!=='reviewing';\n    const canDetails=canUse && id && faState.selected?.status==='reviewing' && Number(faState.selected?.followup)===1;\n    for(const name of ['faFollowupNote','faFollowupDue','faFollowupSaveDetails','faFollowupResetDetails'])\n      faEl(name).disabled=!canDetails;\n  }\n  async function faCopyText(text,label){\n    try{\n      if(!navigator.clipboard?.writeText)throw new Error('Clipboard unavailable');\n      await navigator.clipboard.writeText(text);\n      faNotice(label+' copied (contains no Admin Key or Receipt).');\n    }catch{\n      // Fallback requires deliberate manual copy; never expose a secret here.\n      window.prompt('Copy '+label+':',text);\n      faNotice('Copy '+label+' from the dialog. No private credential was included.');\n    }\n  }\n  async function faOpenCaseById(rawId){\n    const id=String(rawId||'').trim();\n    if(!faCaseIdRx.test(id)){faNotice('Enter a valid Case ID (UUID).',true);return;}\n    if(!faState.key){faNotice('Unlock Staging Admin access before opening a case.',true);return;}\n    if(faState.loading)return;\n    const generation=faState.generation;\n    faSetBusy(true);\n    faNotice('Opening case by ID…');\n    let item=null;\n    try{\n      const result=await faRequest('/api/v1/admin/feedback/case?id='+encodeURIComponent(id));\n      if(generation!==faState.generation || !faState.key)return;\n      if(!result.case || result.case.id.toLowerCase()!==id.toLowerCase())\n        throw new Error('The server returned the wrong case.');\n      item=result.case;\n    }catch(e){\n      faNotice('Unable to open case: '+e.message,true);\n      if(/401|Unauthorized/i.test(e.message))faAuthFailure();\n    }finally{faSetBusy(false);}\n    if(item && faState.key && generation===faState.generation){\n      faEl('faJumpCaseId').value=item.id;\n      await faSelectCase(item);\n    }\n  }\n  function faMoveSelected(delta){\n    if(!faState.selected||faState.loading)return;\n    const idx=faState.cases.findIndex(x=>x.id===faState.selected.id);\n    const next=idx+delta;\n    if(idx<0||next<0||next>=faState.cases.length)return;\n    void faSelectCase(faState.cases[next]);\n  }\n  async function faSelectCase(caseItem){\n    if(faState.loading||!faState.key)return;\n    faState.selected=caseItem;\n    faRenderDetail(caseItem);\n    faEl('faJumpCaseId').value=caseItem.id;\n    faEl('faHistory').replaceChildren(faNode('div','Loading history…','fa-empty'));\n    faSetBusy(true);\n    const token=++faState.requestId;\n    try{\n      const response=await faRequest('/api/v1/admin/feedback/history?id='+encodeURIComponent(caseItem.id));\n      if(token===faState.requestId&&faState.selected?.id===caseItem.id)faRenderHistory(response.history);\n      faNotice('Case opened.');\n    }catch(e){\n      if(token===faState.requestId)faEl('faHistory').replaceChildren(faNode('div','History unavailable.','fa-empty'));\n      faNotice('History request failed: '+e.message,true);\n    }finally{faSetBusy(false);}\n  }\n  async function faRefresh(){\n    if(faState.loading||!faState.key)return;\n    const generation=faState.generation;\n    faSetBusy(true);\n    faNotice('Loading cases…');\n    try{\n      const status=faEl('faStatusFilter').value;\n      const kind=faEl('faKindFilter').value;\n      const search=faEl('faSearch').value.trim();\n      const limit=Number(faEl('faPageSize').value);\n      const sort=faEl('faSortOrder').value;\n      const minAge=faEl('faMinAge').value;\n      if(!faStatuses.has(status)||!['all','feedback','appeal'].includes(kind) ||\n        !['newest','oldest'].includes(sort)||!['0','86400','259200','604800'].includes(minAge)||\n        Array.from(search).length>80 || ![25,50].includes(limit))throw new Error('Invalid filter');\n      const cursor=faState.pageCursors[faState.pageIndex]||'';\n      const followup=faEl('faFollowupFilter').value;\n      const due=faEl('faDueFilter').value;\n      if(!['all','only'].includes(followup) ||\n        !['all','overdue','next24','later','unscheduled','scheduled'].includes(due))\n        throw new Error('Invalid follow-up/due filter');\n      if(due!=='all' && status!=='reviewing')throw new Error('Due filters require Reviewing status');\n      const query=new URLSearchParams({status,kind,search,limit:String(limit),sort,minAge,followup,due});\n      if(due!=='all' && Number.isSafeInteger(faState.dueAsOf) && faState.dueAsOf>0)\n        query.set('dueAsOf',String(faState.dueAsOf));\n      if(cursor)query.set('before',cursor);\n      const [casesResult,summaryResult]=await Promise.allSettled([\n        faRequest('/api/v1/admin/feedback/list?'+query.toString()),\n        faRequest('/api/v1/admin/feedback/summary')\n      ]);\n      if(generation!==faState.generation || !faState.key)return;\n      if(casesResult.status!=='fulfilled')throw casesResult.reason;\n      const data=casesResult.value;\n      if(due!=='all' && !faState.dueAsOf && Number.isSafeInteger(Number(data.asOf)))\n        faState.dueAsOf=Number(data.asOf);\n      faState.cases=Array.isArray(data.cases)?data.cases:[];\n      faState.matchedTotal=Math.max(0,Number(data.matchedTotal)||0);\n      faState.hasMore=data.hasMore===true && typeof data.nextCursor==='string';\n      faState.nextCursor=faState.hasMore?data.nextCursor:null;\n      faClearSelected();faRenderList();\n      if(summaryResult.status==='fulfilled')faRenderSummary(summaryResult.value.summary);\n      else faRenderSummary(null);\n      faNotice('Loaded page '+String(faState.pageIndex+1)+' ('+\n        String(faState.cases.length)+' shown / '+String(faState.matchedTotal)+' matching) from Staging.'+\n        (summaryResult.status==='rejected'?' Queue totals temporarily unavailable.':''));\n      return true; // A successful authenticated case-list response is proof of unlock.\n    }catch(e){\n      if(/401|Unauthorized/i.test(e.message))faAuthFailure();\n      else faNotice('Could not load cases: '+e.message,true);\n      return false;\n    }finally{faSetBusy(false);}\n  }\n  function faFiltersChanged(){\n    if(faSearchTimer){clearTimeout(faSearchTimer);faSearchTimer=null;}\n    faResetPages();\n    if(faState.key && !faState.loading)void faRefresh();\n  }\n  function faNextPage(){\n    if(!faState.key||faState.loading||!faState.hasMore||!faState.nextCursor)return;\n    const next=faState.pageIndex+1;\n    faState.pageCursors[next]=faState.nextCursor;\n    faState.pageCursors.length=next+1;\n    faState.pageIndex=next;\n    void faRefresh();\n  }\n  function faPreviousPage(){\n    if(!faState.key||faState.loading||faState.pageIndex<=0)return;\n    faState.pageIndex--;\n    void faRefresh();\n  }\n  function faRenderActivity(){\n    const list=faEl('faActivityList');list.replaceChildren();\n    const filter=faEl('faActivityFilter').value;\n    const rows=faActivityState.events.filter(e=>filter==='all'||\n      (filter==='submitted' && (e.type==='submitted'||e.type==='imported')) || e.type===filter);\n    for(const entry of rows){\n      const row=faNode('div',undefined,'fa-activity-row');\n      const detail=faNode('div',undefined,'fa-activity-row-main');\n      const eventLabel={submitted:'Submitted',imported:'Existing case imported',edited:'User edited',\n        reviewed:'Moderator reviewed',removed:'Removed'}[entry.type]||'Event';\n      detail.append(faNode('strong',eventLabel+' · '+faText(entry.kind||'Unknown')+' · '+faText(entry.status)));\n      detail.append(faNode('small','Case '+faText(entry.caseId)+' · Revision '+faText(entry.revision)));\n      detail.append(faNode('small',faFormat(entry.createdAt)));\n      row.append(detail);\n      const open=faNode('button',entry.removed?'Removed':'Open case','btn btn-soft btn-sm');\n      open.type='button';open.disabled=entry.removed||!faState.key;\n      if(!open.disabled)open.addEventListener('click',()=>{void faOpenCaseById(entry.caseId);});\n      row.append(open);list.append(row);\n    }\n    if(!rows.length)list.append(faNode('div','No events in the selected view.','fa-empty'));\n  }\n  async function faRefreshActivity(){\n    if(!faState.key||faActivityState.loading)return;\n    const generation=faState.generation;\n    faActivityState.loading=true;\n    faEl('faActivityRefresh').disabled=true;\n    faEl('faActivityStatus').textContent='Loading recent activity…';\n    try{\n      const data=await faRequest('/api/v1/admin/feedback/activity?limit=25');\n      if(generation!==faState.generation||!faState.key)return;\n      faActivityState.events=Array.isArray(data.events)?data.events:[];\n      faRenderActivity();\n      faEl('faActivityStatus').textContent=String(faActivityState.events.length)+\n        ' events loaded · '+faFormat(Math.floor(Date.now()/1000));\n    }catch(e){\n      if(generation!==faState.generation)return;\n      faEl('faActivityStatus').textContent='Activity unavailable: '+faText(e.message);\n      if(/401|Unauthorized/i.test(e.message))faAuthFailure();\n    }finally{\n      faActivityState.loading=false;\n      faEl('faActivityRefresh').disabled=!faState.key;\n    }\n  }\n  function faLock(){\n    faUsersReset();\n    faState.key='';faState.cases=[];faState.requestId++;faState.generation++;\n    faActivityState.events=[];faActivityState.loading=false;\n    faEl('faActivityRefresh').disabled=true;\n    faEl('faActivityList').replaceChildren(faNode('div','Activity is private until admin unlock.','fa-empty'));\n    faEl('faActivityStatus').textContent='Unlock to see the 25 latest events.';\n    if(faSearchTimer){clearTimeout(faSearchTimer);faSearchTimer=null;}\n    faEl('faAdminKey').value='';faEl('faAuthBadge').textContent='LOCKED';\n    faEl('faCount').textContent='—';faClearSelected();faRenderSummary(null);\n    faResetPages();\n    faEl('faCaseList').replaceChildren(faNode('div','Unlock to load cases.','fa-empty'));\n    faEl('faPublicNote').value='';faEl('faAdminNote').value='';\n    faEl('faJumpCaseId').value='';\n    faUpdateSelectionActions();\n    faNotice('Session locked. Admin Key cleared from page memory.');\n  }\n  function faAuthFailure(){\n    // Reject the entire session, not just the visible password field.\n    faLock();\n    faNotice('Admin Key rejected (401). Use the STAGING Admin Key, not a Cloudflare API Token.',true);\n  }\n  async function faUnlock(){\n    if(faState.loading)return;\n    const value=faEl('faAdminKey').value.trim();\n    if(value.length<32){faNotice('Enter a valid Staging Admin Key.',true);return;}\n    faState.key=value;faState.generation++;faEl('faAdminKey').value='';\n    const generation=faState.generation;\n    faEl('faAuthBadge').textContent='VERIFYING';\n    const verified=await faRefresh();\n    if(generation!==faState.generation)return; // Concurrent lock, navigation or rejection.\n    if(verified!==true){\n      faLock();\n      faNotice('Could not verify Admin access. Check the STAGING API connection and retry.',true);\n      return;\n    }\n    await faRefreshActivity();\n    if(generation!==faState.generation || !faState.key)return;\n    faEl('faAuthBadge').textContent='STAGING ADMIN';\n    faUsersUnlocked();\n    const linked=faReadDeepLink();\n    if(linked)await faOpenCaseById(linked);\n  }\n  function faFollowupDateToInput(unix){\n    const n=Number(unix);if(!Number.isFinite(n)||n<=0)return '';\n    const d=new Date(n*1000),p=x=>String(x).padStart(2,'0');\n    return d.getFullYear()+'-'+p(d.getMonth()+1)+'-'+p(d.getDate())+'T'+p(d.getHours())+':'+p(d.getMinutes());\n  }\n  function faFollowupDueFromInput(value){\n    if(!value)return 0;\n    const d=new Date(value),ms=d.getTime();\n    if(!Number.isFinite(ms))return NaN;\n    // Disallow local times which are invalid during daylight-saving transitions.\n    if(faFollowupDateToInput(Math.floor(ms/1000))!==value)return NaN;\n    return Math.floor(ms/1000);\n  }\n  function faResetFollowupDetails(){\n    const c=faState.selected;\n    faEl('faFollowupNote').value=c && Number(c.followup)===1?faText(c.followup_note):'';\n    faEl('faFollowupDue').value=c && Number(c.followup)===1?faFollowupDateToInput(c.followup_due_unix):'';\n    faEl('faFollowupDetailStatus').textContent='Form reset to the selected case details.';\n  }\n  async function faSaveFollowupDetails(){\n    const c=faState.selected;\n    if(!faState.key||faState.loading||!c||c.status!=='reviewing'||Number(c.followup)!==1)return;\n    const note=faEl('faFollowupNote').value.trim(),now=Math.floor(Date.now()/1000);\n    const dueAt=faFollowupDueFromInput(faEl('faFollowupDue').value.trim());\n    if(Array.from(note).length>500 || /[\\u0000-\\u0008\\u000B\\u000C\\u000E-\\u001F]/.test(note)){\n      faNotice('Follow-up reason must be no longer than 500 characters.',true);return;\n    }\n    if(!Number.isSafeInteger(dueAt) || (dueAt!==0 && (dueAt<now+60 || dueAt>now+365*86400))){\n      faNotice('Choose a valid return date between 1 minute and 365 days from now, or clear it.',true);return;\n    }\n    if(note===faText(c.followup_note).trim() && dueAt===Number(c.followup_due_unix||0)){\n      faEl('faFollowupDetailStatus').textContent='No changes to follow-up details.';return;\n    }\n    if(!window.confirm('Save private follow-up details for '+faText(c.id)+'?\\n\\nNote: '+String(Array.from(note).length)+' characters\\nDue: '+(dueAt?faFormat(dueAt):'none')+'\\n\\nOnly admin reviewers can read these details.'))return;\n    const generation=faState.generation;\n    faSetBusy(true);faNotice('Saving private follow-up details to STAGING…');\n    let success=false;\n    try{\n      const result=await faRequest('/api/v1/admin/feedback/followup/details','POST',{\n        id:c.id,note,dueAt,expectedFollowupUpdatedAt:Number(c.followup_updated_unix)\n      });\n      if(generation!==faState.generation || !faState.key)return;\n      if(result.id!==c.id||result.followup!==true)throw new Error('Unexpected server response');\n      success=true;faNotice('Private follow-up details saved.');\n    }catch(e){\n      if(generation!==faState.generation)return;\n      faNotice('Unable to save follow-up details: '+faText(e.message)+'; refresh the case.',true);\n      if(/401|Unauthorized/i.test(e.message))faAuthFailure();\n    }finally{faSetBusy(false);}\n    if(success && faState.key && generation===faState.generation){\n      await faRefresh();\n      if(faState.key)await faOpenCaseById(c.id);\n    }\n  }\n  async function faToggleFollowup(){\n    if(!faState.key||faState.loading||!faState.selected)return;\n    const c=faState.selected;\n    if(c.status!=='reviewing'){\n      faNotice('Only Reviewing cases can be marked for follow-up.',true);return;\n    }\n    const marked=Number(c.followup)===1, enabled=!marked;\n    const question=(enabled?'Mark':'Clear')+' manual follow-up for case '+faText(c.id)+'?\\n\\n'+\n      'This does not approve, deny or otherwise change the case review decision.';\n    if(!window.confirm(question))return;\n    const generation=faState.generation;\n    let success=false;\n    faSetBusy(true);faNotice('Updating manual follow-up on Staging…');\n    try{\n      const result=await faRequest('/api/v1/admin/feedback/followup','POST',{\n        id:c.id,enabled,expectedFollowup:marked\n      });\n      if(generation!==faState.generation||!faState.key)return;\n      if(result.followup!==enabled)throw new Error('Unexpected server follow-up response');\n      success=true;\n      faNotice(enabled?'Marked for follow-up.':'Follow-up cleared.');\n    }catch(e){\n      if(generation!==faState.generation)return;\n      faNotice('Follow-up update rejected: '+faText(e.message)+'. Refresh case and retry.',true);\n      if(/401|Unauthorized/i.test(e.message))faAuthFailure();\n    }finally{faSetBusy(false);}\n    if(success && faState.key && generation===faState.generation){\n      await faRefresh();\n      if(faState.key)await faOpenCaseById(c.id);\n    }\n  }\n  async function faSave(){\n    if(!faState.selected||faState.loading||!faState.key)return;\n    const c=faState.selected;\n    const status=faEl('faDecision').value;\n    const publicNote=faEl('faPublicNote').value;\n    const adminNote=faEl('faAdminNote').value;\n    if(!faStatuses.has(status)||Array.from(publicNote).length>800||Array.from(adminNote).length>1000){\n      faSaveNotice('Invalid status or note length.',true);return;\n    }\n    if(status===c.status && publicNote===faText(c.public_note) && adminNote===faText(c.admin_note)){\n      faSaveNotice('Nothing changed.');return;\n    }\n    const message='Confirm staging moderation update?\\n\\nCase: '+faText(c.id)+'\\n'+faText(c.status)+' → '+status+'\\nPublic reply: '+Array.from(publicNote).length+' characters\\nPrivate note: '+Array.from(adminNote).length+' characters';\n    if(!window.confirm(message))return;\n    faSetBusy(true);\n    faSaveNotice('Saving decision to Staging…');\n    let saved=false;\n    try{\n      await faRequest('/api/v1/admin/feedback','POST',{\n        id:c.id,status,publicNote,adminNote,expectedUpdatedAt:Number(c.updated_unix)\n      });\n      saved=true;\n      faSaveNotice('Saved. Synchronizing cases and queue totals…');\n      faNotice('Decision saved successfully.');\n      // After a successful update, immediately clear the outdated client snapshot.\n      faClearSelected();faState.cases=[];\n      faEl('faCaseList').replaceChildren(faNode('div','Decision saved. Refresh to load current cases.','fa-empty'));\n    }catch(e){\n      faSaveNotice('Save rejected: '+e.message+' — refresh before retrying.',true);\n      faNotice('Failed to save. Check the version and connection.',true);\n    }finally{faSetBusy(false);}\n    if(saved && faState.key){\n      await faRefresh();\n      // Keep the reviewed case visible even when its new status moves it\n      // out of the current queue filter.\n      if(faState.key)await faOpenCaseById(c.id);\n      if(faState.key)await faRefreshActivity();\n    }\n  }\n\n  // --- STAGING User's Case native bridge (retains original Admin session) ---\n  const FA_TRASH_API='https://arcscriptcenter-trash-admin-staging.kogpasan14.workers.dev';\n  const FA_TRASH_PATH='/api/v1/admin/feedback/unknown-trash';\n  let faUsersToken=0;\n  let faUsersCache=[];\n  let faUsersView=null;\n  let faUsersIsLoading=false;\n  let faTrashIsLoading=false;\n  function faUsersReset(){\n    ++faUsersToken;\n    faUsersCache=[];faUsersView=null;\n    faEl('faUsersGroups').replaceChildren();\n    faEl('faUsersCases').replaceChildren();\n    faEl('faUsersCases').hidden=true;\n    faEl('faUnknownTrash').hidden=true;\n    faEl('faTrashCases').replaceChildren();\n    faEl('faUsersSearch').value='';\n    faEl('faUsersStatus').textContent='Unlock Admin access, then select Load User\\'s Case.';\n    faEl('faTrashStatus').textContent='Not loaded.';\n    faEl('faUsersLoad').disabled=true;\n    faEl('faTrashLoad').disabled=true;\n  }\n  function faUsersUnlocked(){\n    const enabled=!!faState.key&&!faState.loading;\n    faEl('faUsersLoad').disabled=!enabled;\n    faEl('faTrashLoad').disabled=!enabled;\n  }\n  async function faTrashRequest(page=0,action=null,id=null){\n    const generation=faState.generation;\n    const key=faState.key;\n    if(!key)throw new Error('Unlock Admin access first');\n    if(!Number.isInteger(page)||page<0||page>9999)throw new Error('Invalid page');\n    const method=action?'POST':'GET';\n    const path=FA_TRASH_API+FA_TRASH_PATH+(method==='GET'?'?page='+page:'');\n    const payload=action?{action,id,confirm:action==='move'?'MOVE UNKNOWN CASE TO TRASH':'RESTORE UNKNOWN CASE'}:null;\n    const result=await fetch(path,{\n      method,mode:'cors',credentials:'omit',cache:'no-store',redirect:'error',\n      headers:{Accept:'application/json','X-Admin-Key':key,\n        ...(method==='POST'?{'Content-Type':'application/json'}:{})},\n      ...(payload?{body:JSON.stringify(payload)}:{})\n    });\n    if(generation!==faState.generation||!faState.key||key!==faState.key)throw new Error('Admin session changed');\n    let data;try{data=await result.json();}catch{throw new Error('Invalid Trash API response');}\n    if(!result.ok||data?.ok!==true||data?.adminOnly!==true)\n      throw new Error(String(data?.error||'Trash API unavailable')+' (HTTP '+result.status+')');\n    return data;\n  }\n  function faUsersMatches(group,raw){\n    if(!raw)return true;\n    const query=raw.toLowerCase();\n    return String(group.claimedId||'').toLowerCase().includes(query)||\n      String(group.username||'').toLowerCase().includes(query)||\n      String(group.displayName||'').toLowerCase().includes(query)||\n      (group.claimedId===null && 'unknown / unlinked'.includes(query));\n  }\n  function faUsersRender(){\n    if(!faState.key)return;\n    const query=faEl('faUsersSearch').value.trim().toLowerCase();\n    const groups=faUsersCache.filter(g=>faUsersMatches(g,query));\n    const node=faEl('faUsersGroups');node.replaceChildren();\n    const view=faEl('faUsersCases');view.replaceChildren();view.hidden=true;\n    if(!groups.length)node.append(faNode('div','No matching UserId / known Username.','fa-empty'));\n    for(const group of groups){\n      const btn=faNode('button',undefined,'fa-user-group');btn.type='button';\n      const label=group.claimedId===null?'Unknown / Unlinked':\n        (group.username?'@'+group.username+' · ':'')+'UserId '+group.claimedId;\n      btn.append(faNode('strong',label),faNode('small',group.cases.length+' cases · unverified claim'));\n      btn.addEventListener('click',()=>faUsersShowGroup(group));\n      node.append(btn);\n    }\n  }\n  function faUsersShowGroup(group){\n    if(!faState.key)return;\n    faUsersView=group.claimedId;\n    const region=faEl('faUsersCases');region.replaceChildren();region.hidden=false;\n    const label=group.claimedId===null?'Unknown / Unlinked':\n      (group.username?'@'+group.username+' · ':'')+'UserId '+group.claimedId;\n    region.append(faNode('h4',label),faNode('p','Names are public profile information or existing Admin records; ownership of Feedback is not verified.','fa-inline-status'));\n    const cases=[...group.cases].sort((a,b)=>Number(b.updated_unix)-Number(a.updated_unix));\n    for(const c of cases){\n      const row=faNode('div',undefined,'fa-users-case-row');\n      row.append(faNode('strong',String(c.topic||'(Untitled)')),\n        faNode('small',String(c.kind)+' · '+String(c.status)+' · '+String(c.id)));\n      const actions=faNode('div',undefined,'fa-case-action-row');\n      const open=faNode('button','Open Case','btn btn-soft');open.type='button';\n      open.addEventListener('click',()=>{void faOpenCaseById(c.id)});\n      actions.append(open);\n      if(group.claimedId===null && c.kind==='feedback'){\n        const move=faNode('button','Move Unknown Case To Trash','btn');move.type='button';\n        move.addEventListener('click',()=>{void faUsersMoveToTrash(c,move)});\n        actions.append(move);\n      }\n      row.append(actions);region.append(row);\n    }\n    region.scrollIntoView?.({behavior:'smooth',block:'nearest'});\n  }\n  async function faUsersMoveToTrash(c,button){\n    if(!faState.key||c.kind!=='feedback'||!(c.claimed_user_id==null || String(c.claimed_user_id).trim()===''))return;\n    if(!window.confirm('Move this UNKNOWN Feedback case to Trash?\\nCase '+c.id+'\\nIt will be permanently deleted after 30 days. You may Restore before that deadline.'))return;\n    button.disabled=true;\n    const token=faState.generation;\n    try{\n      const response=await faTrashRequest(0,'move',c.id);\n      if(response.id!==c.id||response.action!=='move')throw new Error('Unexpected move confirmation');\n      if(token!==faState.generation)return;\n      faEl('faUsersStatus').textContent='Moved to Trash. Permanent deletion is scheduled for '+faFormat(response.purgeAt)+'.';\n      faUsersCache=[];faEl('faUsersGroups').replaceChildren();faEl('faUsersCases').hidden=true;\n      await Promise.allSettled([faUsersLoad(),faTrashLoad(),faRefresh()]);\n    }catch(e){if(token===faState.generation){faEl('faUsersStatus').textContent='Move failed: '+String(e.message)}}\n    finally{button.disabled=false;}\n  }\n  async function faTrashRestore(id,btn,now){\n    if(!faState.key||!faCaseIdRx.test(id))return;\n    if(!window.confirm('Restore Unknown Feedback case '+id+' from Trash?'))return;\n    btn.disabled=true;\n    const generation=faState.generation;\n    try{\n      const r=await faTrashRequest(0,'restore',id);\n      if(r.id!==id||r.action!=='restore')throw new Error('Restore failed');\n      if(generation!==faState.generation)return;\n      await Promise.allSettled([faTrashLoad(),faUsersLoad(),faRefresh()]);\n    }catch(e){if(generation===faState.generation)faEl('faTrashStatus').textContent='Restore failed: '+e.message;}\n    finally{btn.disabled=false;}\n  }\n  async function faTrashLoad(){\n    if(!faState.key||faTrashIsLoading)return;\n    faTrashIsLoading=true;\n    const token=faState.generation;\n    const panel=faEl('faUnknownTrash');panel.hidden=false;\n    const list=faEl('faTrashCases');list.replaceChildren();\n    faEl('faTrashStatus').textContent='Loading Trash…';\n    try{\n      let total=0;\n      for(let p=0;p<12;p++){\n        const data=await faTrashRequest(p);\n        if(token!==faState.generation)return;\n        if(!Array.isArray(data.items))throw new Error('Unexpected Trash list');\n        for(const c of data.items){\n          const row=faNode('div',undefined,'fa-trash-row');\n          row.append(faNode('strong',c.topic||'Untitled Feedback'),\n            faNode('small','Case '+c.id+' · Delete after '+faFormat(c.purgeAt)));\n          const restore=faNode('button','Restore','btn btn-soft');restore.type='button';\n          restore.disabled=Number(c.purgeAt)<=Math.floor(Date.now()/1000);\n          restore.addEventListener('click',()=>{void faTrashRestore(c.id,restore)});\n          row.append(restore);list.append(row);total++;\n        }\n        if(!data.hasMore){faEl('faTrashStatus').textContent=total+' cases in Trash.';return;}\n      }\n      faEl('faTrashStatus').textContent=total+' Trash cases loaded (maximum 300; more may exist).';\n    }catch(e){if(token===faState.generation)faEl('faTrashStatus').textContent='Trash request failed: '+e.message;}\n    finally{faTrashIsLoading=false;}\n  }\n  async function faUsersLoad(){\n    if(!faState.key||faUsersIsLoading)return;\n    const token=++faUsersToken;\n    const generation=faState.generation;\n    faUsersIsLoading=true;\n    faEl('faUsersLoad').disabled=true;\n    faEl('faUsersStatus').textContent='Loading User\\'s Case…';\n    try{\n      const cases=[];let capped=false;\n      for(const status of ['reviewing','approved','denied','violation','spam_mail']){\n        let cursor='';\n        for(let page=0;page<8;page++){\n          const q=new URLSearchParams({status,kind:'all',sort:'newest',limit:'50'});\n          if(cursor)q.set('before',cursor);\n          const data=await faRequest('/api/v1/admin/feedback/list?'+q.toString());\n          if(token!==faUsersToken||generation!==faState.generation)return;\n          if(!Array.isArray(data.cases))throw new Error('Invalid Admin case list response');\n          cases.push(...data.cases);\n          if(!data.hasMore)break;\n          if(typeof data.nextCursor!=='string'||!data.nextCursor)throw new Error('Pagination cursor missing');\n          cursor=data.nextCursor;\n          if(page===7)capped=true;\n        }\n      }\n      let banned=[];\n      try{\n        const out=await faRequest('/api/v1/admin/bans');\n        if(Array.isArray(out.entries))banned=out.entries;\n      }catch{/* Optional public name hint from existing Ban Management; case identities remain unverified. */}\n      if(token!==faUsersToken||generation!==faState.generation)return;\n      const usernames=new Map(banned.filter(v=>v&&v.userId&&v.username).map(v=>[String(v.userId),String(v.username)]));\n      const groups=new Map();\n      const seen=new Set();\n      for(const c of cases){\n        if(!faCaseIdRx.test(String(c.id||''))||seen.has(c.id))continue;\n        seen.add(c.id);\n        const id=c.claimed_user_id===null||c.claimed_user_id===undefined||!String(c.claimed_user_id).trim()?null:String(c.claimed_user_id).trim();\n        const key=id||'__unlinked__';\n        if(!groups.has(key))groups.set(key,{claimedId:id,username:id?usernames.get(id)||'':'',cases:[]});\n        groups.get(key).cases.push(c);\n      }\n      faUsersCache=[...groups.values()].sort((a,b)=>a.claimedId===null?-1:b.claimedId===null?1:\n        (Math.max(...b.cases.map(c=>Number(c.updated_unix)||0))-Math.max(...a.cases.map(c=>Number(c.updated_unix)||0))));\n      faUsersRender();\n      faEl('faUsersStatus').textContent=faUsersCache.length+' groups · '+cases.length+' cases'+\n        (capped?' · Partial listing; maximum 400 per status reached':'')+'. Click a user to view cases.';\n    }catch(e){if(token===faUsersToken&&generation===faState.generation)faEl('faUsersStatus').textContent='User\\'s Case failed: '+e.message;}\n    finally{faUsersIsLoading=false;faUsersUnlocked();}\n  }\n  faEl('faUsersLoad').addEventListener('click',()=>{void faUsersLoad()});\n  faEl('faTrashLoad').addEventListener('click',()=>{void faTrashLoad()});\n  faEl('faUsersSearch').addEventListener('input',()=>{if(faState.key)faUsersRender();});\n  faUsersReset();\n  // End STAGING User's Case bridge.\n\n  faEl('faUnlock').addEventListener('click',()=>{void faUnlock();});\n  faEl('faLock').addEventListener('click',faLock);\n  faEl('faRefresh').addEventListener('click',()=>{faResetPages();void faRefresh();});\n  faEl('faActivityRefresh').addEventListener('click',()=>{void faRefreshActivity();});\n  faEl('faActivityFilter').addEventListener('change',faRenderActivity);\n  faEl('faStatusFilter').addEventListener('change',()=>{\n    if(faEl('faStatusFilter').value!=='reviewing')faEl('faDueFilter').value='all';\n    faFiltersChanged();\n  });\n  faEl('faKindFilter').addEventListener('change',faFiltersChanged);\n  faEl('faSortOrder').addEventListener('change',faFiltersChanged);\n  faEl('faMinAge').addEventListener('change',faFiltersChanged);\n  faEl('faFollowupFilter').addEventListener('change',()=>{\n    if(faEl('faFollowupFilter').value==='all')faEl('faDueFilter').value='all';\n    faFiltersChanged();\n  });\n  faEl('faDueFilter').addEventListener('change',()=>{\n    if(faEl('faDueFilter').value!=='all'){\n      faEl('faStatusFilter').value='reviewing';\n      faEl('faFollowupFilter').value='only';\n    }\n    faFiltersChanged();\n  });\n  faEl('faFollowupToggle').addEventListener('click',()=>{void faToggleFollowup();});\n  faEl('faFollowupSaveDetails').addEventListener('click',()=>{void faSaveFollowupDetails();});\n  faEl('faFollowupResetDetails').addEventListener('click',faResetFollowupDetails);\n  faEl('faPageSize').addEventListener('change',faFiltersChanged);\n  faEl('faPagePrev').addEventListener('click',faPreviousPage);\n  faEl('faPageNext').addEventListener('click',faNextPage);\n  faEl('faPreviousCase').addEventListener('click',()=>faMoveSelected(-1));\n  faEl('faNextCase').addEventListener('click',()=>faMoveSelected(1));\n  faEl('faJumpCase').addEventListener('click',()=>{void faOpenCaseById(faEl('faJumpCaseId').value);});\n  faEl('faJumpCaseId').addEventListener('keydown',e=>{\n    if(e.key==='Enter'){e.preventDefault();void faOpenCaseById(faEl('faJumpCaseId').value);}\n  });\n  faEl('faCopyCaseId').addEventListener('click',()=>{\n    if(faState.selected)void faCopyText(faState.selected.id,'Case ID');\n  });\n  faEl('faCopyCaseLink').addEventListener('click',()=>{\n    if(faState.selected)void faCopyText(faCaseLink(faState.selected.id),'case link');\n  });\n  window.addEventListener('hashchange',()=>{\n    const linked=faReadDeepLink();\n    if(linked && faState.key && !faState.loading)void faOpenCaseById(linked);\n  });\n  faEl('faSearch').addEventListener('input',()=>{\n    if(faSearchTimer)clearTimeout(faSearchTimer);\n    faSearchTimer=setTimeout(()=>{faSearchTimer=null;faFiltersChanged();},450);\n  });\n  faEl('faShowPendingAppeals').addEventListener('click',()=>{\n    faEl('faStatusFilter').value='reviewing';\n    faEl('faKindFilter').value='appeal';\n    faEl('faMinAge').value='0';\n    faEl('faFollowupFilter').value='all';\n    faEl('faDueFilter').value='all';\n    faEl('faSearch').value='';\n    if(faState.key)faFiltersChanged();\n    else faNotice('Unlock Staging Admin access before viewing appeals.',true);\n  });\n  faEl('faShowFollowups').addEventListener('click',()=>{\n    faEl('faStatusFilter').value='reviewing';\n    faEl('faKindFilter').value='all';\n    faEl('faMinAge').value='0';\n    faEl('faSortOrder').value='oldest';\n    faEl('faFollowupFilter').value='only';\n    faEl('faDueFilter').value='all';\n    faEl('faSearch').value='';\n    if(faState.key)faFiltersChanged();\n    else faNotice('Unlock Staging Admin access to view manual follow-ups.',true);\n  });\n  // Manual queue jump only. Never save, notify, or change a case automatically.\n  function faViewDueBucket(bucket){\n    faEl('faStatusFilter').value='reviewing';\n    faEl('faKindFilter').value='all';\n    faEl('faFollowupFilter').value='only';\n    faEl('faDueFilter').value=bucket;\n    faEl('faMinAge').value='0';\n    faEl('faSortOrder').value='oldest';\n    faEl('faSearch').value='';\n    if(faState.key)faFiltersChanged();\n    else faNotice('Unlock Staging Admin access before browsing the due queue.',true);\n  }\n  faEl('faShowOverdue').addEventListener('click',()=>faViewDueBucket('overdue'));\n  faEl('faShowDueSoon').addEventListener('click',()=>faViewDueBucket('next24'));\n  faEl('faShowNoDue').addEventListener('click',()=>faViewDueBucket('unscheduled'));\n  faEl('faSave').addEventListener('click',()=>{void faSave();});\n  faEl('faReset').addEventListener('click',()=>{if(faState.selected)faRenderDetail(faState.selected);});\n  faEl('faAdminKey').addEventListener('keydown',e=>{if(e.key==='Enter'){e.preventDefault();void faUnlock();}});\n  window.addEventListener('pagehide',faLock);\n})();\n";
const REQUIRE = ['id="page-bans"','data-page="bans"','data-page="audit"','id="breadcrumb"','id="sidebar"'];
// Stage 16.50: security headers are applied to the HTML response of
// BOTH successful integration and safe fallback without altering Dashboard JS.
function hardenHtmlHeaders(original, integrationState) {
  const h = new Headers(original);
  h.set('Cache-Control', 'private, no-store, max-age=0');
  h.set('Pragma', 'no-cache');
  h.set('X-Content-Type-Options', 'nosniff');
  h.set('X-Frame-Options', 'DENY');
  h.set('Referrer-Policy', 'no-referrer');
  h.set('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
  h.set('X-Robots-Tag', 'noindex, nofollow, noarchive, nosnippet');
  // Preserve preexisting script/style policies; tighten framing/objects only.
  // Do not introduce script-src/default-src: the original Pages Dashboard
  // contains inline JavaScript and must keep functioning.
  const originalCsp = h.get('Content-Security-Policy') || '';
  const directives = originalCsp.split(';').map(s => s.trim()).filter(Boolean)
    .filter(s => !/^frame-ancestors(?:\s|$)/i.test(s) && !/^object-src(?:\s|$)/i.test(s));
  if (!directives.some(s => /^base-uri(?:\s|$)/i.test(s))) directives.push("base-uri 'self'");
  directives.push("frame-ancestors 'none'", "object-src 'none'");
  h.set('Content-Security-Policy', directives.join('; '));
  h.set('X-ASC1650-Security', 'hardened');
  if (integrationState) h.set('X-ASC1649-Integration', integrationState);
  return h;
}
const BAN_MODE_SCRIPT = "/* ArcScriptCenter — Native Banned Check Center Ban Selection PREVIEW.\n * Adds fields to the EXISTING banEditorForm and labels to banRecords.\n * Reuses the existing Ban Center Admin Key input. Never logs or stores it.\n * IMPORTANT: Existing staging /admin/bans GET is read-only and its schema is v1.\n * This preview intentionally blocks all ban POSTs rather than claiming to save\n * Selection/Duration fields that the backend does not yet persist.\n */\n(()=>{'use strict';\n const panel=document.getElementById('page-bans');\n const form=document.getElementById('banEditorForm');\n const records=document.getElementById('banRecords');\n const keyField=document.getElementById('banAdminKey');\n const endField=document.getElementById('banEnd');\n if(!panel||!form||!records||!keyField||!endField||document.getElementById('banSelection'))return;\n const grid=form.querySelector('.form-grid');\n if(!grid)return;\n const doc=panel.ownerDocument;\n const node=(tag,text,cls)=>{const el=doc.createElement(tag);if(text!==undefined)el.textContent=text;if(cls)el.className=cls;return el};\n const field=(id,labelText,options)=>{\n  const wrap=node('div',undefined,'field');\n  const label=node('label',labelText);label.htmlFor=id;\n  const select=node('select');select.id=id;select.className='search';select.required=true;\n  for(const [value,title] of options){const option=node('option',title);option.value=value;select.append(option)}\n  wrap.append(label,select);return {wrap,select};\n };\n const selection=field('banSelection','Ban Selection *',[\n  ['','Choose Ban Selection'],['ban_ingame','Ban in-game — SetUp only'],['restricted_mode','Restricted Mode — limited Main Loader']\n ]);\n const duration=field('banDuration','Ban Duration *',[\n  ['temporary','Temporary — expires at the date below'],['permanent','Permanent — no expiry']\n ]);\n const note=node('p','STAGING Preview: GitHub saving is disabled until the Ban API supports Selection + Duration. Save to QA Sandbox stores test records only.','field-note');\n note.id='banModeNotice';note.setAttribute('role','status');note.style.gridColumn='1 / -1';\n grid.insertBefore(selection.wrap,grid.firstChild);\n grid.insertBefore(duration.wrap,selection.wrap.nextSibling);\n grid.insertBefore(note,duration.wrap.nextSibling);\n const list=new Map();let loadId=0;let locked=true;\n // The original native Ban Unlock handler clears its input after reading.\n // Capture that same key ONLY in this tab's closure, before it is cleared.\n // No second Login, URL parameters, cookies or browser storage.\n let sessionKey='';\n const qaEndpoint='https://arcscriptcenter-ban-v2-qa.kogpasan14.workers.dev/api/v1/admin/bans/v2/qa';\n const qaState={revision:0,entries:[],loaded:false,busy:false};\n\n const idMatch=/User ID ([1-9][0-9]{0,15})/;\n const status=msg=>{note.textContent=msg};\n const classify=e=>{\n  const mode=e?.selection==='ban_ingame'?'Ban in-game':\n   e?.selection==='restricted_mode'?'Restricted Mode':'Selection not set (legacy: SetUp-only)';\n  const length=e?.expiresAt?'Temporary':'Permanent';\n  return {mode,length};\n };\n function syncDuration(){\n  endField.required=duration.select.value==='temporary';\n  if(duration.select.value==='permanent')endField.value='';\n }\n duration.select.addEventListener('change',syncDuration);\n endField.addEventListener('change',()=>{duration.select.value=endField.value?'temporary':'permanent';syncDuration()});\n function updateCards(){\n  for(const card of records.querySelectorAll('.quick-row')){\n   const name=card.querySelector('strong');\n   const id=idMatch.exec(name?.textContent||'')?.[1];\n   if(!id)continue;\n   const item=list.get(id);\n   const {mode,length}=classify(item);\n   let label=card.querySelector('[data-ban-mode-label]');\n   if(!label){label=node('small');label.dataset.banModeLabel='true';label.className='asc-ban-selection-label';label.style.display='block';label.style.marginTop='5px';name.parentElement?.append(label)}\n   const value='Selection: '+mode+'  |  Duration: '+length;\n   if(label.textContent!==value)label.textContent=value;\n  }\n }\n async function reload(){\n  const key=sessionKey;\n  const generation=++loadId;\n  if(typeof key!=='string'||key.length<32){\n   locked=true;list.clear();updateCards();\n   status('Unlock existing Banned Check Center Admin access to view saved Selection and Duration.');\n   return;\n  }\n  try{\n   const r=await fetch('https://arcscriptcenter-api-staging.kogpasan14.workers.dev/api/v1/admin/bans',{\n    method:'GET',mode:'cors',credentials:'omit',cache:'no-store',redirect:'error',\n    headers:{'Accept':'application/json','X-Admin-Key':key}\n   });\n   if(generation!==loadId||sessionKey!==key)return;\n   const data=await r.json();\n   if(!r.ok||data?.ok!==true||!Array.isArray(data.entries))throw Error('Not authorized or unavailable');\n   list.clear();for(const entry of data.entries)if(/^[1-9][0-9]{0,15}$/.test(String(entry?.userId||'')))list.set(String(entry.userId),entry);\n   locked=false;updateCards();\n   status('Ban Selection and Duration are shown below. STAGING schema v1 remains read-only; no changes will be saved.');\n  }catch{\n   if(generation===loadId){locked=true;list.clear();updateCards();status('Cannot read Ban selections. Unlock Admin access again.')}\n  }\n }\n function fillFromSelected(id){\n  const item=list.get(id);\n  if(!item){selection.select.value='';duration.select.value='permanent'}\n  else{selection.select.value=['ban_ingame','restricted_mode'].includes(item.selection)?item.selection:'';\n   duration.select.value=item.expiresAt?'temporary':'permanent';}\n  syncDuration();\n }\n records.addEventListener('click',e=>{\n  if(!(e.target instanceof Element)||e.target.textContent?.trim()!=='Edit')return;\n  const card=e.target.closest('.quick-row');\n  const id=idMatch.exec(card?.querySelector('strong')?.textContent||'')?.[1];\n  if(id)queueMicrotask(()=>fillFromSelected(id));\n });\n const observer=new MutationObserver(()=>{updateCards()});\n observer.observe(records,{childList:true,subtree:true});\n document.getElementById('banUnlock')?.addEventListener('click',()=>{\n  sessionKey=keyField.value.trim();\n  if(sessionKey.length<32){sessionKey='';return;}\n  setTimeout(()=>{void reload();void qaLoad();},850);\n },true);\n document.getElementById('banRefresh')?.addEventListener('click',()=>{\n  setTimeout(()=>{void reload();void qaLoad();},150);\n });\n document.getElementById('banLock')?.addEventListener('click',()=>{\n  loadId++;sessionKey='';list.clear();locked=true;\n  qaState.entries=[];qaState.revision=0;qaState.loaded=false;renderQa();\n  selection.select.value='';duration.select.value='permanent';syncDuration();\n  updateCards();status('Locked. Existing Admin session and list are cleared from this preview.');\n });\n document.getElementById('banClear')?.addEventListener('click',()=>{\n  selection.select.value='';duration.select.value='permanent';syncDuration()\n });\n\n // Save to a separate QA D1 only. This never commits the live GitHub ban block.\n const actionRow=form.querySelector('.form-actions');\n const saveQa=node('button','Save to QA Sandbox');\n saveQa.type='button';saveQa.id='banSaveQaOnly';saveQa.className='btn btn-soft';\n const loadQaButton=node('button','Load QA Bans');\n loadQaButton.type='button';loadQaButton.id='banLoadQaOnly';loadQaButton.className='btn';\n if(actionRow)actionRow.append(saveQa,loadQaButton);\n const qaPanel=node('section',undefined,'panel panel-pad');\n qaPanel.id='banQaOnlyPanel';qaPanel.style.marginTop='18px';\n const qaHeading=node('h3','QA Sandbox — not active bans');\n const qaMessage=node('p','Unlock the existing Admin account to test saving Ban Selection v2. Nothing here affects Roblox users.','field-note');\n qaMessage.id='banQaStatus';qaMessage.setAttribute('role','status');\n const qaRecords=node('div');qaRecords.id='banQaRecords';qaRecords.className='list-stack';\n qaPanel.append(qaHeading,qaMessage,qaRecords);\n records.parentElement?.append(qaPanel);\n\n function qaStatus(message){qaMessage.textContent=String(message)}\n function renderQa(){\n  qaRecords.replaceChildren();\n  if(!qaState.loaded){qaRecords.append(node('p','QA list is locked or not loaded.'));return}\n  if(qaState.entries.length===0){qaRecords.append(node('p','No QA entries.'));return}\n  for(const entry of qaState.entries){\n   const row=node('div',undefined,'fa-user-case-row');\n   row.style.padding='10px';row.style.border='1px solid var(--line)';\n   row.style.marginTop='8px';\n   row.append(\n    node('strong',(entry.username||'Unknown username')+' · UserId '+entry.userId+' [QA ONLY]'),\n    node('p','Selection: '+(entry.selection==='restricted_mode'?'Restricted Mode':entry.selection==='ban_ingame'?'Ban in-game':'Unassigned legacy')),\n    node('p','Duration: '+(entry.duration==='temporary'?'Temporary':'Permanent')+\n      (entry.expiresAt?' · Until '+entry.expiresAt+' ICT':''))\n   );\n   const edit=node('button','Edit QA entry');edit.type='button';edit.className='btn btn-sm';\n   edit.addEventListener('click',()=>{\n    if(!sessionKey)return;\n    doc.getElementById('banUserId').value=entry.userId;\n    doc.getElementById('banUserId').readOnly=false;\n    doc.getElementById('banUsername').value=entry.username;\n    doc.getElementById('banReason').value=entry.reason;\n    doc.getElementById('banDescription').value=entry.description;\n    doc.getElementById('banStart').value=entry.startAt.replace(' ','T');\n    endField.value=entry.expiresAt.replace(' ','T');\n    selection.select.value=entry.selection==='unassigned'?'':entry.selection;\n    duration.select.value=entry.duration;syncDuration();\n    qaStatus('QA entry loaded into editor. No live ban is affected.');\n   });\n   row.append(edit);qaRecords.append(row);\n  }\n }\n async function qaRequest(method,payload){\n  const key=sessionKey,generation=loadId;\n  if(!key||key.length<32)throw Error('Unlock the existing Admin account first');\n  const response=await fetch(qaEndpoint,{\n   method,mode:'cors',credentials:'omit',redirect:'error',cache:'no-store',\n   headers:{Accept:'application/json','X-Admin-Key':key,\n     ...(method==='POST'?{'Content-Type':'application/json'}:{})},\n   ...(method==='POST'?{body:JSON.stringify(payload)}:{})\n  });\n  if(key!==sessionKey||loadId!==generation)throw Error('Admin session changed');\n  let data;\n  try{data=await response.json()}catch{throw Error('Invalid QA API response')}\n  if(!response.ok||data?.ok!==true||data?.adminOnly!==true||data?.qaOnly!==true)\n   throw Error(data?.error||'QA API returned '+response.status);\n  return data;\n }\n async function qaLoad(){\n  if(qaState.busy)return;\n  qaState.busy=true;qaStatus('Loading isolated QA records…');\n  try{\n   const data=await qaRequest('GET');\n   if(data.document?.schema!==2||!Array.isArray(data.document.entries)||\n      !Number.isSafeInteger(data.revision))throw Error('Invalid QA schema');\n   qaState.entries=data.document.entries;\n   qaState.revision=data.revision;qaState.loaded=true;\n   renderQa();qaStatus('QA Sandbox loaded. Revision '+data.revision+'. Never affects actual bans.');\n  }catch(e){qaState.loaded=false;qaState.entries=[];renderQa();qaStatus('QA Load: '+e.message)}\n  finally{qaState.busy=false}\n }\n function entryFromForm(){\n  const value=id=>doc.getElementById(id).value.trim();\n  return {userId:value('banUserId'),username:value('banUsername'),\n   reason:value('banReason'),description:value('banDescription'),\n   startAt:doc.getElementById('banStart').value.replace('T',' '),\n   expiresAt:endField.value.replace('T',' '),\n   selection:selection.select.value,duration:duration.select.value};\n }\n saveQa.addEventListener('click',async()=>{\n  if(qaState.busy)return;\n  if(!sessionKey){qaStatus('Unlock existing Admin access first.');return}\n  const entry=entryFromForm();\n  if(!/^[1-9][0-9]{0,15}$/.test(entry.userId)||\n     !['ban_ingame','restricted_mode'].includes(entry.selection)||\n     !['temporary','permanent'].includes(entry.duration)||\n     (entry.duration==='temporary'&&!entry.expiresAt)||\n     (entry.duration==='permanent'&&entry.expiresAt)||\n     entry.reason.length<3){\n   qaStatus('Invalid form: select Ban Type, Duration, and required fields.');\n   return;\n  }\n  if(!window.confirm('Save UserId '+entry.userId+' to QA ONLY? This does not ban anyone or change GitHub.'))return;\n  qaState.busy=true;saveQa.disabled=true;\n  try{\n   if(!qaState.loaded){qaState.busy=false;await qaLoad();qaState.busy=true}\n   if(!qaState.loaded)throw Error('QA list could not be loaded');\n   const result=await qaRequest('POST',{action:'upsert',entry,expectedRevision:qaState.revision});\n   if(result.document?.schema!==2||!result.saved)throw Error('QA Save was not confirmed');\n   qaState.entries=result.document.entries;qaState.revision=result.revision;\n   qaState.loaded=true;renderQa();\n   qaStatus('Saved to QA Sandbox, revision '+result.revision+'. No live ban was changed.');\n  }catch(e){qaStatus('QA Save rejected: '+e.message+' (refresh QA records before retry)')}\n  finally{qaState.busy=false;saveQa.disabled=false}\n });\n loadQaButton.addEventListener('click',()=>{void qaLoad()});\n renderQa();\n\n // PREVIEW-ONLY: The existing submit script serializes v1 fields and would\n // silently discard Selection; stop the submit BEFORE the original listener.\n form.addEventListener('submit',e=>{\n  e.preventDefault();e.stopImmediatePropagation();\n  status('GitHub Save is disabled while schema v1 is live. Use Save to QA Sandbox to test v2 only.');\n },true);\n duration.select.value='permanent';syncDuration();updateCards();\n})();\n";
