export default {
  async fetch(request,env) {
    const url=new URL(request.url);
    if(request.method==='GET' && url.pathname==='/__asc1649/feedback-appeal.css')
      return new Response(MOD_STYLES, {headers:headers('text/css')});
    if(request.method==='GET' && url.pathname==='/__asc1649/feedback-appeal.js')
      return new Response(MOD_SCRIPT, {headers:headers('text/javascript')});
    if(request.method==='GET' && url.pathname==='/__asc1650/ban-mode.js')
      return new Response(BAN_MODE_SCRIPT, {headers:headers('text/javascript')});
    const response=await env.ASSETS.fetch(request);
    if(request.method!=='GET' || !['/','/index.html'].includes(url.pathname) ||
       response.status!==200 || !(response.headers.get('content-type')||'').includes('text/html'))
      return response;
    const original=await response.text();
    const addBanUI=original.includes('id="page-bans"') && original.includes('id="banEditorForm"')
      && !original.includes('/__asc1650/ban-mode.js');
    if(original.includes('id="page-feedback-appeal"') || original.includes('data-page="feedback-appeal"')) {
      // The 17 Nov canonical HTML already has native Feedback + Appeal.
      // Inject ONLY the new User's Case panel next to its existing queue.
      // Keep every existing navigation item, Admin Key input, assets and script tag.
      if(!original.includes('id="faUsersCase"') && original.includes('class="fa-layout"')) {
        const start=MOD_SECTION.indexOf('<div class="panel panel-pad fa-users-panel" id="faUsersCase"');
        const finish=MOD_SECTION.indexOf('<div class="fa-layout">',start);
        if(start>=0 && finish>start){
          const extra=MOD_SECTION.slice(start,finish);
          const rewritten=new HTMLRewriter()
            .on('#page-feedback-appeal .fa-layout',{element(e){e.before(extra,{html:true});}})
            .on('body',{element(e){if(addBanUI)e.append(BAN_MODE_TAG,{html:true});}})
            .transform(new Response(original,{status:response.status,headers:response.headers}));
          const h=hardenHtmlHeaders(rewritten.headers,'injected-users-case-native');
          return new Response(rewritten.body,{status:rewritten.status,headers:h});
        }
      }
      if(addBanUI){
        const rewritten=new HTMLRewriter()
          .on('body',{element(e){e.append(BAN_MODE_TAG,{html:true});}})
          .transform(new Response(original,{status:response.status,headers:response.headers}));
        const h=hardenHtmlHeaders(rewritten.headers,'injected-ban-selection-preview');
        return new Response(rewritten.body,{status:rewritten.status,headers:h});
      }
      const h=hardenHtmlHeaders(response.headers,'skipped-already-installed');
      return new Response(original,{status:response.status,headers:h});
    }
    if(!REQUIRE.every(s=>original.includes(s))){
      const h=hardenHtmlHeaders(response.headers,'skipped-unrecognized-layout');
      return new Response(original,{status:response.status,headers:h});
    }
    // HTMLRewriter ensures the EXACT original site HTML stays intact apart from
    // the new sibling nav + content section and stylesheet/script references.
    const transformed=new HTMLRewriter()
      .on('[data-page="bans"]',{element(e){e.after(MOD_NAV,{html:true});}})
      .on('#page-bans',{element(e){e.after(MOD_SECTION,{html:true});}})
      .on('head',{element(e){e.append('<link rel="stylesheet" href="/__asc1649/feedback-appeal.css">',{html:true});}})
      .on('body',{element(e){e.append('<script defer src="/__asc1649/feedback-appeal.js"></script>',{html:true});if(addBanUI)e.append(BAN_MODE_TAG,{html:true});}})
      .transform(new Response(original,{status:response.status,headers:response.headers}));
    const h=hardenHtmlHeaders(transformed.headers,'injected-staging-preview');
    return new Response(transformed.body,{status:transformed.status,headers:h});
  }
};
